/* ===== পেইজ ট্রানজিশন: মেনু ট্যাপ করলে ফেড-আউট + স্পিনার, তারপর নতুন পেইজ ফুটে ওঠে ===== */
(function(){
 try{
  var root=document.documentElement,reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  function mk(){
   if(document.getElementById('nf-ld')&&document.getElementById('nf-ld').className==='nf-real')return;
   var d=document.createElement('div');d.id='nf-ld';d.className='nf-real';d.setAttribute('aria-hidden','true');
   d.innerHTML='<div class="nf-sp"></div>';document.body.appendChild(d);
  }
  if(document.body)mk();else document.addEventListener('DOMContentLoaded',mk);
  document.addEventListener('click',function(e){
   if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
   var a=e.target&&e.target.closest?e.target.closest('a[href]'):null;if(!a)return;
   if(a.target&&a.target!=='_self')return;if(a.hasAttribute('download'))return;
   var h=a.getAttribute('href');
   if(!h||h.charAt(0)==='#'||/^(mailto:|tel:|javascript:|sms:|whatsapp:)/i.test(h))return;
   var u;try{u=new URL(a.href,location.href)}catch(x){return}
   if(u.origin!==location.origin)return;
   if(u.pathname===location.pathname&&u.search===location.search)return;
   e.preventDefault();mk();
   if(reduce){location.assign(u.href);return}
   root.classList.add('nf-leaving');
   setTimeout(function(){location.assign(u.href)},230);
   setTimeout(function(){root.classList.remove('nf-leaving')},10000);
  });
  /* ব্যাক বাটন চাপলে যেন স্পিনার আটকে না থাকে */
  window.addEventListener('pageshow',function(ev){root.classList.remove('nf-leaving')});
 }catch(err){console.error('nf-transition',err)}
})();

